<section class="assessment-head"><p class="eyebrow"><?= $assessment['type']==='final_exam'?'EXAMEN FINAL':'COMPOSITION DE SECTION' ?></p><h1><?= htmlspecialchars($assessment['title']) ?></h1><p><?= htmlspecialchars($assessment['course_title']) ?> · Seuil de réussite : <?= $assessment['passing_score'] ?>%</p></section><form class="assessment-form" method="post" action="/academie/composition"><input type="hidden" name="assessment_id" value="<?= $assessment['id'] ?>"><?php if(!$questions): ?><div class="panel admin-empty">Cette évaluation ne contient pas encore de questions.</div><?php endif ?><?php foreach($questions as $i=>$question): $options=json_decode($question['options'],true)?:[]; ?><article class="panel question-card"><span>QUESTION <?= $i+1 ?> / <?= count($questions) ?></span><h2><?= htmlspecialchars($question['question']) ?></h2><?php foreach($options as $option): ?><label><input type="radio" name="answers[<?= $question['id'] ?>]" value="<?= htmlspecialchars($option) ?>" required><b></b><?= htmlspecialchars($option) ?></label><?php endforeach ?></article><?php endforeach ?><?php if($questions): ?><button class="btn primary assessment-submit">Terminer et envoyer mes réponses →</button><?php endif ?></form><style>.assessment-head,.assessment-form{max-width:800px;margin:0 auto 25px}.assessment-head{text-align:center}.question-card{padding:25px;margin-bottom:15px}.question-card>span{font-size:8px;color:var(--primary);font-weight:700}.question-card h2{font-size:16px;margin:10px 0 20px}.question-card label{padding:12px;border:1px solid var(--line);display:flex;gap:10px;margin:7px 0;border-radius:8px;cursor:pointer}.question-card label:has(input:checked){border-color:var(--primary);background:#f4f2ff}.assessment-submit{float:right}</style>
